preConditionHook:
// MultiWalk's WFSafe_AvgTrueRange is a ROLLING accumulator, not a fresh N-term
// sum: seeded with a full sum on the study's first calculated bar, thereafter
// carrying S += TrueRange - TrueRange[Length], re-seeding when the length
// changes. Same block as AtrProfitTarget, including the TWO separate
// accumulator statements -- EasyLanguage evaluates
// Summation[1] + Price - Price[Length] left to right, and folding it to
// S += in - out rounds differently. It stays in the hook, which the generator
// emits unconditionally, because EasyLanguage does not short-circuit and/or.
if (atrLenState != (int)atrLength) {
    atrSum = 0.0;
    for (int i = 0; i < (int)atrLength; ++i) {
        double hi = high[i] > close[i + 1] ? high[i] : close[i + 1];
        double lo = low[i] < close[i + 1] ? low[i] : close[i + 1];
        atrSum += hi - lo;
    }
    atrLenState = (int)atrLength;
} else {
    const int out = (int)atrLength;
    double hiIn = high[0] > close[1] ? high[0] : close[1];
    double loIn = low[0] < close[1] ? low[0] : close[1];
    double hiOut = high[out] > close[out + 1] ? high[out] : close[out + 1];
    double loOut = low[out] < close[out + 1] ? low[out] : close[out + 1];
    atrSum += hiIn - loIn;
    atrSum -= hiOut - loOut;
}
atrValue = atrSum / (int)atrLength;
// Mirrors EasyLanguage's Extremes(), which Highest()/Lowest() call: seeded at
// bar 0 (the window INCLUDES the current bar), scanning bars 1..Length-1 with a
// strict comparison so a tie keeps the earliest bar. Extremes is EL SOURCE, so
// its comparisons carry the ordinary relational tolerance and use el_gt/el_lt.
// The distance is measured to the closing price, not to this bar's own low or high:
// Brooks reads the resumption from where the bar settled. That is also what
// separates this rule from PullbackFromRecentHigh, whose two sides are these
// two exchanged and taken to the bar's extreme.
recentHigh = high[0];
recentLow = low[0];
for (int i = 1; i < (int)lookback; ++i) {
    if (el_gt(high[i], recentHigh)) recentHigh = high[i];
    if (el_lt(low[i], recentLow)) recentLow = low[i];
}
